3	/**
4	 * Single definition of how an owner telephone is normalized: strip every non-digit
5	 * character. Both {@link NormalizeOwnerTelephone} (which normalizes the incoming request)
6	 * and {@link EnsureUniqueOwnerTelephone} (which normalizes stored owners for comparison)
7	 * call this, so the create-time rule and the dedup comparison can never silently diverge.
8	 */
9	final class OwnerTelephones {
10	
11	    private OwnerTelephones() {
12	    }
13	
14	    /** Returns {@code telephone} with every non-digit character removed ("" when null). */
15	    static String normalize(String telephone) {
16	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
17	    }
18	}
